+static void radix_sort(uint32_t* a, uint32_t* tmp, size_t n) {
+    if (n <= 1) return;
+    for (int pass = 0; pass < PASSES; ++pass) {
+        uint32_t* count = new uint32_t[256]();
+        uint32_t shift = pass * RADIX_BITS;
+        uint32_t mask = (1 << RADIX_BITS) - 1;
+
+        // Compute histograms
+        for (size_t i = 0; i < n; ++i) {
+            count[(a[i] >> shift) & mask]++;
+        }
+
+        // Compute prefix sums
+        uint32_t total = 0;
+        for (int i = 0; i < 256; ++i) {
+            total += count[i];
+            count[i] = total;
+        }
+
+        // Scatter elements
+        for (size_t i = n; i-- > 0; ) {
+            uint32_t key = (a[i] >> shift) & mask;
+            tmp[--count[key]] = a[i];
+        }
+
+        // Copy back
+        std::memcpy(a, tmp, n * sizeof(uint32_t));
+
+        delete[] count;
+    }
